 foreach($it as $f){if(!$f->isFile()||$f->isLink())continue;$r=substr($f->getPathname(),strlen($root)+1);$top=explode('/',$r)[0];if(str_starts_with($top,'_')||in_array($top,['.git','.github'],true)||isset($targets[$r]))continue;$out[$r]=hash_file('sha256',$f->getPathname());}
 foreach(['config.php','production.php'] as $n)$out['private/'.$n]=ui_hash(__DIR__.'/'.$n);ksort($out);return $out;
}
function ui_atomic(string $p,string $bytes):void{
